from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import cycloplegie,atropine
l=Lesson('Strabisme')
cyclo=cycloplegie(l);atro=atropine(l)
l.add('Le {strabisme est un désalignement pathologique des axes visuels}. Un œil peut fixer l’objet pendant que l’autre dévie. Il peut être constant ou intermittent, ancien ou acquis.',paras('Le Royal College of Ophthalmologists définit ainsi le strabisme dans son guide de 2012 ; les HUG décrivent le défaut de coordination entre les deux yeux. Une ésotropie dévie vers le nez, une exotropie vers la tempe, une hypertropie vers le haut et une hypotropie vers le bas.', 'Une tropie est manifeste en vision binoculaire ; une phorie est une déviation latente révélée lorsque la fusion est interrompue. Un pseudostrabisme correspond à une apparence trompeuse sans déviation démontrée : l’inspection seule ne suffit pas à rassurer.', 'La diplopie binoculaire disparaît en fermant l’un ou l’autre œil. Une diplopie persistant lorsque seul l’œil atteint regarde évoque plutôt une cause monoculaire. L’enfant peut supprimer l’image de l’œil dévié et ne signaler aucune vision double malgré un risque d’amblyopie.'),(1,2,3,5,6))
l.add('Le {risque dépend de l’âge, du terrain et de l’histoire visuelle}. L’enfant risque une amblyopie et une mauvaise vision binoculaire. Une apparition acquise impose de chercher une cause oculaire, neurologique ou musculaire.',paras('La brochure des HUG de 2018, réimprimée en 2021, rapporte 2–4 % des enfants et environ 5 % de la population générale. Ce sont des estimations d’information aux patients, sans dénominateur national suisse détaillé ; elles ne classent pas les causes de strabisme.', 'Prématurité, troubles du développement, antécédents familiaux, hypermétropie et atteinte organique oculaire augmentent le risque. Une baisse de vision peut être conséquence de la déviation ou cause d’un strabisme sensoriel.', 'La gêne psychosociale, la position compensatrice de tête et les difficultés de lecture ou de travail comptent dans la décision. Une déviation petite ou intermittente n’est pas automatiquement sans retentissement. L’incidence suisse récente par sous-type et les coûts comparatifs ne sont pas établis dans les sources consultées.'),(1,2,3,6))
an=l.subwindow('anatomie','Muscles, nerfs et développement binoculaire',paras('Six muscles mobilisent chaque globe. Le nerf abducens, VI, commande le droit latéral. Le trochléaire, IV, commande l’oblique supérieur. Le nerf oculomoteur, III, innerve les autres muscles oculomoteurs et le releveur de paupière. Sa composante parasympathique intervient dans la constriction pupillaire et l’accommodation.', 'Les noyaux siègent dans le tronc cérébral ; leurs connexions coordonnent les regards des deux yeux. Une atteinte centrale, nerveuse, de la jonction neuromusculaire ou de l’orbite peut donc désaligner les axes. Une restriction mécanique ne signifie pas nécessairement paralysie d’un nerf.', 'La mise au point de près associe accommodation et convergence. Chez l’enfant hypermétrope, l’effort accommodatif peut entraîner une convergence excessive, réduite par la correction optique. Une réfraction sans cycloplégie peut sous-estimer l’hypermétropie.', 'Le cortex combine normalement les informations des deux yeux. Une entrée visuelle asymétrique précoce peut produire suppression et amblyopie. Une correction de l’angle ne répare pas automatiquement une amblyopie déjà installée.'),(1,3,5,6))
l.add('Les {bases anatomiques expliquent les tests et les traitements}. La déviation peut provenir de la commande, de la transmission, du muscle ou de la vision. Le mécanisme détermine le bilan avant la correction de l’angle.',paras(an)+table(['Perturbation','Exploration','Action dirigée'],[['L’accommodation entraîne une convergence excessive.','La réfraction cycloplégique et la mesure sous lunettes montrent la composante optique.','La correction hypermétropique réduit l’effort accommodatif.'],['Une image est supprimée durant le développement.','L’acuité monoculaire et les tests sensoriels recherchent une amblyopie.','La correction puis l’occlusion ou la pénalisation entraînent l’œil moins performant.'],['Une commande nerveuse manque.','La motilité, les pupilles et l’imagerie ciblée localisent la lésion.','La cause est traitée avant une correction symptomatique durable.'],['Le tissu orbitaire devient restrictif.','L’examen orbital et l’imagerie évaluent muscle et nerf optique.','Le traitement contrôle l’inflammation ; la chirurgie traite certaines séquelles stables.']]),(1,3,5,6,11,12))
l.add('Le {tri commence par les menaces visuelles et neurologiques}. Un strabisme soudain mérite une évaluation rapide. Une leucocorie, une baisse de vision ou des signes neurologiques associés accélèrent l’orientation.',table(['Priorité','Signe recherché','Action immédiate'],[['🚩 E1','Une paralysie acquise du III apparaît, surtout avec douleur ou mydriase.','Organiser un bilan urgent avec imagerie vasculaire ; une pupille normale ne suffit pas à exclure l’anévrisme.'],['🚩 E1','L’enfant présente un strabisme nouveau avec reflet rouge absent, leucocorie, céphalée, vomissement ou ataxie.','Adresser immédiatement en ophtalmologie ou en pédiatrie aiguë selon le signe ; rechercher notamment rétinoblastome ou hypertension intracrânienne.'],['🚩 E1','La diplopie accompagne un déficit focal, un trouble de conscience ou une céphalée brutale.','Activer le parcours d’urgence neurologique ; appeler le 144 si nécessaire.'],['🚩 E1','Une orbitopathie s’accompagne de baisse d’acuité, altération des couleurs ou atteinte cornéenne.','Faire évaluer immédiatement le nerf optique et la cornée.'],['🚩 E1','Un ptosis fluctuant accompagne dysphagie, dysarthrie ou difficulté respiratoire.','Rechercher une généralisation myasthénique et organiser une surveillance urgente.'],['🚩 E2','Une paralysie oculomotrice acquise survient sans autre alarme.','Obtenir rapidement l’évaluation spécialisée ; chez l’enfant, l’absence de céphalée ne suffit pas à rassurer.']])+paras('La liste des dix diagnostics ne remplace pas le tri : accident vasculaire, fracture avec incarcération, hémorragie, infection orbitaire et artérite à cellules géantes restent des causes à rechercher selon le contexte. Ne pas retarder un traitement causal urgent pour mesurer parfaitement l’angle.'),(4,5,9,12,13,16))
l.add('L’{anamnèse précise le début et les circonstances de la déviation}. Rechercher anciennes photographies, diplopie, fatigue et torticolis. Les symptômes associés déterminent le degré d’urgence.',paras('Demander si la déviation existait sur des photographies anciennes, si elle varie entre près et loin et si elle s’accentue à la fatigue. Une fluctuation peut être strabique ou myasthénique ; elle ne prouve pas une origine bénigne.', 'Rechercher antécédents de lunettes, occlusion, opération, prématurité, problème périnatal et atteinte familiale. Chez l’adulte, demander traumatisme, diabète, hypertension, maladie thyroïdienne et antécédents vasculaires.', 'Questionner baisse visuelle, reflet blanc, douleur, céphalée, vomissements, déséquilibre, trouble de déglutition et faiblesse. Après 50 ans, une céphalée nouvelle, une douleur à la mastication ou des symptômes généraux font rechercher une artérite à cellules géantes.', 'Recueillir les médicaments et collyres avant d’interpréter la pupille. Demander si la personne conduit ou exerce un travail exposant autrui : la diplopie active impose de suspendre une activité dangereuse en attendant l’évaluation.'),(1,3,4,5))
l.add('L’{examen compare la vision et la motilité des deux yeux}. Observer d’abord la posture, les pupilles et les reflets rouges. Mesurer ensuite l’alignement de près et de loin, avec la correction portée.',table(['Étape','Normal attendu et technique','Anomalie et conséquence'],[['Acuité monoculaire','Tester séparément chaque œil avec un outil adapté à l’âge et une occlusion complète.','Une différence demande réfraction et recherche de cause organique ; une bonne acuité binoculaire peut masquer la mauvaise vision d’un œil.'],['Reflets et pupilles','Comparer les reflets rouges et la réaction lumineuse avant les gouttes.','Une leucocorie, une asymétrie ou un déficit pupillaire afférent impose un examen spécialisé.'],['Test à l’écran','Faire fixer une cible ; couvrir un œil et observer le mouvement de refixation de l’œil resté découvert.','Un mouvement révèle une déviation manifeste ; le test alterné dissocie davantage la fusion et mesure la déviation totale.'],['Quantification','Neutraliser le mouvement avec des prismes lors du bilan orthoptique ; préciser fixation et lunettes.','Documenter les dioptries prismatiques, la direction et la variation selon le regard.'],['Motilité','Faire suivre une cible sans mouvement de tête ; examiner les versions puis les ductions si nécessaire.','Une limitation, une rétraction du globe, un nystagmus ou une douleur change l’orientation.'],['Fond d’œil','L’examen dilaté évalue rétine, macula et papille.','Ne pas attribuer une baisse de vision à l’amblyopie avant d’avoir recherché une lésion.']])+paras('Un examen impossible ou peu fiable doit être noté et réorganisé ; il ne compte pas comme normal. Le spécialiste adapte les tests à l’enfant préverbal. La dilatation peut gêner la conduite ; informer avant les instillations.'),(1,3,5,6))
l.add('L’{approche syndromique organise les dix hypothèses}. Décrire la direction ne suffit pas à nommer la cause. L’âge, la comitance, la vision et les signes associés doivent être rapprochés.',paras('7.1. Une déviation comitante garde un angle relativement comparable selon le regard : les formes accommodatives, infantiles et intermittentes sont recherchées. Une comitance n’exclut pas une cause neurologique devant un début aigu.', '7.2. Une déviation incomitante change avec la direction du regard : examiner limitation, torsion et posture. Une paralysie, une restriction ou une dysinnervation congénitale peuvent expliquer ce profil.', '7.3. Un strabisme sensoriel accompagne une mauvaise vision ; rechercher rétine, cristallin, cornée et nerf optique. Une leucocorie ne doit jamais être simplement étiquetée amblyopie.', '7.4. Un profil fatigable associe fluctuation de la déviation et parfois ptosis. Rechercher les signes extraoculaires d’une myasthénie sans s’arrêter à l’absence d’anomalie pupillaire.')+comparison(),(1,2,3,4,5,9,10,11,13))
l.add('Le {diagnostic positif associe déviation démontrée et caractérisation}. Le bilan orthoptique précise angle, contrôle et fonction binoculaire. La cause nécessite parfois une exploration supplémentaire.',paras('Le test à l’écran et les mesures prismatiques sont cliniques : aucun chiffre unique de déviation ne définit toutes les formes. Distinguer déviation manifeste et latente, constante et intermittente, comitante et incomitante.', 'L’ésotropie accommodative se caractérise par l’amélioration sous correction hypermétropique complète ; une composante résiduelle doit être décrite. L’ésotropie infantile du guide britannique est constante avant six mois. Un strabisme nouvellement constaté n’a pas nécessairement commencé ce jour-là.', 'La mesure de l’acuité, de la réfraction et du fond d’œil accompagne le diagnostic. Un test de stéréoscopie normal isolé, une photo rassurante ou l’absence de plainte ne remplace pas ce bilan. Aucun biomarqueur ne confirme à lui seul toutes les causes de strabisme.'),(1,3,6))
l.add('Les {examens complémentaires sont choisis selon la question}. La réfraction sous cycloplégie complète le bilan de l’enfant. Une suspicion neurologique, tumorale ou orbitaire détermine l’imagerie et son urgence.',paras('9.a. La référence pour caractériser l’alignement est l’examen ophtalmologique et orthoptique ; il n’existe pas d’examen biologique unique du strabisme. Une imagerie identifie une cause, pas la seule déviation.', '9.b. En première intention, mesurer acuités et réfraction, examiner pupilles, motilité et fond d’œil. Pour la cycloplégie, vérifier les conditions suisses avant toute instillation : '+cyclo, '9.c. Si l’enfant coopère peu, adapter fixation et méthode, puis réexaminer ; une observation difficile n’autorise pas à conclure à une vision normale. Une anesthésie peut être nécessaire pour un bilan tumoral spécialisé, mais n’est pas systématique pour une réfraction.', '9.d. Selon les alarmes, demander imagerie cérébrale, orbitaire ou vasculaire ; bilan thyroïdien, anticorps ou électrophysiologie répondent à une hypothèse ciblée. Informer la radiologie d’une grossesse, d’une insuffisance rénale, d’une allergie au contraste ou d’un dispositif implanté afin d’adapter le protocole sans retarder l’urgence.')+table(['Résultat','Interprétation','Suite'],[['La correction réduit la convergence.','Une composante accommodative est présente.','Mesurer l’angle résiduel et contrôler la vision.'],['Une limitation persiste dans une direction.','Une paralysie, une restriction ou une dysinnervation est possible.','Localiser cliniquement et explorer la cause selon l’ancienneté.'],['Le reflet rouge ou le fond d’œil est anormal.','Une atteinte organique est possible.','Accélérer le bilan spécialisé.'],['Les tests ne concordent pas ou sont peu fiables.','Le diagnostic reste incomplet.','Répéter l’examen et rechercher l’explication de la discordance.']]),(1,3,4,5,6,7))
l.add('L’{arbre décisionnel place l’urgence avant l’alignement}. Après le tri, séparer déviation comitante, paralytique, restrictive et sensorielle. Réévaluer la cause si la réponse au traitement ne correspond pas à l’hypothèse.',steps('Rechercher immédiatement baisse de vision, leucocorie, paralysie acquise du III, signes neurologiques, orbitaires ou myasthéniques graves.', 'Si une alarme est présente, organiser l’évaluation urgente et traiter la cause sans attendre un bilan orthoptique exhaustif.', 'Sans alarme immédiate, confirmer la déviation et mesurer séparément la vision de chaque œil.', 'Chez l’enfant, effectuer réfraction et examen organique ; caractériser la réponse à la correction et traiter l’amblyopie.', 'Si limitation, fluctuation ou signes orbitaires sont présents, explorer respectivement nerf, jonction neuromusculaire ou orbite.', 'Planifier suivi et correction symptomatique ; toute aggravation, nouveau symptôme ou réponse inattendue relance le bilan causal.'),(1,3,4,5,6,12,13,16))
l.add('La {prise en charge vise la vision, le confort et l’alignement}. Corriger la réfraction et traiter l’amblyopie selon le bilan. Les prismes ou la chirurgie répondent ensuite à une indication individualisée.',paras('11.A. Définir avec le patient des objectifs mesurables : acuité de chaque œil, angle sous correction, fréquence de diplopie, posture et fonction binoculaire. Aucun seuil de guérison unique ne convient à toutes les causes.', '11.B. Pour une forme non compliquée, prescrire les lunettes adaptées et organiser l’apprentissage du port. L’occlusion ou la pénalisation est ajustée à la réponse visuelle, avec surveillance des deux yeux : '+atro, '11.B. Les prismes peuvent soulager certaines diplopies ; ils ne traitent pas une compression nerveuse. La chirurgie agit sur les muscles et peut améliorer confort, posture et apparence. Elle ne remplace pas les lunettes ou le traitement de l’amblyopie lorsqu’ils restent nécessaires.', '11.C. Devant une menace vitale ou visuelle, adresser immédiatement à l’équipe appropriée. Un anévrisme, une tumeur, une neuropathie optique ou une crise myasthénique exige son traitement propre ; masquer la diplopie ne règle pas le danger.', '11.D. Chez l’enfant, surveiller le développement visuel et la tolérance au traitement. Chez la personne enceinte, âgée ou insuffisante rénale ou hépatique, individualiser médicaments et examens avec leurs notices et contre-indications. Une sortie ambulatoire suppose une cause suffisamment évaluée, l’absence d’urgence non traitée, des consignes comprises, un accompagnement si vision altérée et un contrôle organisé.', 'Vérifier les conditions de remboursement des dispositifs auprès de l’assurance ; la brochure des HUG ne constitue pas une décision individuelle de prise en charge. Expliquer le traitement à l’école ou au travail avec l’accord du patient ou des parents. La reprise de la conduite requiert une vision compatible et une évaluation adaptée.'),(1,2,3,6,8,12,13,16))
l.add('La {prévention repose sur le repérage et le suivi visuel}. Un enfant qui ne se plaint pas peut avoir une amblyopie. Un traitement réussi demande encore une surveillance des récidives.',paras('La prévention primaire ne peut pas supprimer toutes les formes congénitales. Informer les familles des signes d’appel et protéger les yeux lors des activités exposées évite certains retards ou traumatismes.', 'La prévention secondaire repose sur les contrôles pédiatriques et l’orientation si un strabisme même intermittent est observé. Jules-Gonin recommande un contrôle précoce vers un an en cas d’antécédents familiaux de strabisme ou d’amblyopie ; un signe anormal impose de consulter plus tôt.', 'La prévention tertiaire associe observance des lunettes, suivi de l’acuité, adaptation de l’occlusion et soutien psychosocial. Une récidive ou une baisse visuelle malgré le traitement nécessite une nouvelle recherche de cause.', 'Les recommandations françaises de 2022 de dépistage précisent un parcours national distinct ; elles étayent les tests utiles sans être présentées comme une obligation suisse. Ne pas promettre un taux individuel de guérison à partir d’un chiffre général de brochure.'),(1,2,3,6))
l.add('Les {décisions essentielles commencent par la cause}. Une déviation nouvelle peut annoncer une urgence. L’amblyopie et l’angle se traitent séparément, avec suivi des deux yeux.',paras('Ne pas rassurer sur la seule absence de diplopie chez l’enfant. Ne pas assimiler une pupille normale à l’exclusion d’un anévrisme dans une paralysie acquise du III. Ne pas repousser une leucocorie à un contrôle de routine.', 'Mesurer la vision de chaque œil avant de choisir le traitement. Rechercher une cause organique si la vision baisse ou si le résultat déçoit. Garder la correction optique et la surveillance même lorsque l’apparence s’améliore.'),(1,3,4,6,16))
l.quiz([('L’absence de diplopie exclut-elle un strabisme chez l’enfant ?','Non ; la suppression peut masquer la vision double.'),('Une phorie est-elle une déviation toujours manifeste ?','Non ; elle est latente et révélée par la dissociation.'),('Une déviation comitante aiguë prouve-t-elle la bénignité ?','Non ; l’histoire et les signes associés restent essentiels.'),('Que faire devant strabisme nouveau et leucocorie ?','Organiser immédiatement un examen ophtalmologique.'),('Que faire devant strabisme, vomissements et ataxie chez l’enfant ?','Adresser immédiatement en pédiatrie aiguë.'),('Une pupille normale exclut-elle l’anévrisme dans une paralysie du III ?','Non ; une imagerie doit être organisée dès la présentation.'),('Une bonne vision avec les deux yeux ouverts exclut-elle une amblyopie ?','Non ; il faut mesurer chaque œil séparément.'),('La direction de la déviation donne-t-elle seule son origine ?','Non ; causes accommodative, nerveuse, restrictive ou sensorielle peuvent se ressembler.'),('La chirurgie d’alignement remplace-t-elle le traitement de l’amblyopie ?','Non.'),('Peut-on utiliser Cyclogyl avant un an selon la notice suisse lue ?','Non ; la notice indique de ne pas l’utiliser avant cet âge.'),('L’atropine en collyre reste-t-elle sans risque systémique ?','Non ; une absorption et une toxicité anticholinergique sont possibles.'),('Une occlusion doit-elle être poursuivie sans contrôle ?','Non ; il faut surveiller les deux yeux et ajuster la prescription.'),('Un strabisme ancien peut-il se décompenser chez l’adulte ?','Oui, après avoir évalué les nouvelles causes et les urgences.'),('Les dix numéros constituent-ils une prévalence suisse démontrée ?','Non ; les sources ne permettent pas ce classement comparatif.')],(1,2,3,4,5,6,7,8,16))
l.write()
